edits.to:
// Keep the single sprite visible beyond the clipped foreground:
// a fixed child of the Page Builder is independent of section scroll.
const fixedHost = scene.closest('.mskba-page-builder');
if (fixedHost) {
    if (root.parentElement !== fixedHost) fixedHost.append(root);
    root.style.position = 'fixed';
    root.style.zIndex = '7';
    root.style.left = dockX.toFixed(2) + 'px';
    root.style.top = dockY.toFixed(2) + 'px';
} else {
    assignOwner(true, ballHost);
    root.style.left = (dockX - hostRect.left).toFixed(2) + 'px';
    root.style.top = (dockY - hostRect.top).toFixed(2) + 'px';
}
root.style.setProperty('--ball-scale', activeProfile.endScale.toFixed(4));
